from grounding import study_policies as policies
def predict(ctx, baseline):
 try:
  return policies.direct(ctx,request_pixels=4194304)
 except Exception as e:
  detail=getattr(e,'response',None)
  body=detail.text if detail is not None else str(e)
  import modal
  modal.Dict.from_name('ensemble-desktop-localization-study-state')['resolution-probe']=body
  return {'point':None,'diagnostic_error':body}
